parameters.jsCode:
const email = $input.item.json.body.email;
const name = $input.item.json.body.name || 'Melómano de Sonar';
const topics = $input.item.json.body.topics || ['Lanzamientos', 'Hi-Fi', 'Festivales'];
const timestamp = new Date().toISOString();

const emailHtml = `
<div style="font-family: 'Helvetica Neue', Arial, sans-serif; max-width: 600px; margin: 0 auto; background: #231123; color: #FAF5F8; border-radius: 20px; overflow: hidden; border: 1px solid #4B2840;">
  <div style="background: linear-gradient(135deg, #5c1d5e 0%, #B80C09 100%); padding: 32px 24px; text-align: center;">
    <h1 style="margin: 0; font-size: 26px; font-weight: 900; letter-spacing: 0.1em; color: #FFFFFF;">SONAR · NOTICIAS & RADAR AUDIÓFILO</h1>
    <p style="margin: 8px 0 0; font-size: 13px; color: #FDDDE6;">Buen criterio. Mejor música.</p>
  </div>
  <div style="padding: 32px 24px;">
    <h2 style="font-size: 20px; font-weight: 800; color: #FFFFFF;">¡Bienvenido al boletín, ${name}!</h2>
    <p style="font-size: 14px; line-height: 1.6; color: #DCDCDD;">Te has suscrito con éxito al radar semanal de Sonar. Cada semana recibirás análisis de nuevos lanzamientos, guías de hardware analógico, crónicas de festivales y reediciones audiófilas exclusivas.</p>
    <div style="background: #4B2840; border-radius: 12px; padding: 16px; margin: 20px 0;">
      <h3 style="margin: 0 0 8px; font-size: 12px; text-transform: uppercase; color: #ff8c8a; font-weight: 800;">Tus temas seleccionados:</h3>
      <ul style="margin: 0; padding-left: 20px; font-size: 13px; color: #FAF5F8;">
        ${topics.map(t => `<li>${t}</li>`).join('')}
      </ul>
    </div>
    <p style="font-size: 12px; color: #A08C9D;">Si deseas personalizar tus temas o pausar el boletín, visita tu perfil en <a href="http://localhost:5173/#usuario" style="color: #B80C09; text-decoration: none; font-weight: bold;">Sonar</a>.</p>
  </div>
</div>
`;

return {
  json: {
    email,
    name,
    topics,
    timestamp,
    subject: '¡Bienvenido al Radar Semanal de Sonar!',
    emailHtml
  }
};

parameters.responseBody:
={
  "success": true,
  "message": "¡Suscripción confirmada! Te hemos enviado un correo de bienvenida a " + $json.email + ".",
  "subscriber": {
    "email": $json.email,
    "name": $json.name,
    "topics": $json.topics,
    "subscribedAt": $json.timestamp
  }
}
